    --layout-card-direction: column;
    --layout-animation-style: kinetic-split-reveal;
    --font-weight-active: 800;
}

#news-container {
    max-width: var(--layout-max-width);
    margin: 10rem auto;
    padding: 0 2rem;
    display: grid;
    grid-template-columns: var(--layout-news-columns);
    gap: var(--layout-card-gap);
    /* マソンリー的な変則配置をシミュレート */
    align-items: start;
}

.news-card {
    position: relative;
